CREATE TABLE IF NOT EXISTS official_travel_type (code VARCHAR(32) PRIMARY KEY, name VARCHAR(120) NOT NULL, approval_target VARCHAR(16) NOT NULL, sort_order INT NOT NULL, updated_at DATETIME NOT NULL) DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO official_travel_type (code, name, approval_target, sort_order, updated_at) VALUES ('IN_PROVINCE', 'ในจังหวัด', 'HOSPITAL', 1, UTC_TIMESTAMP()), ('OUT_OF_PROVINCE', 'ต่างจังหวัด', 'HOSPITAL', 2, UTC_TIMESTAMP()), ('ABROAD', 'ต่างประเทศ', 'HOSPITAL', 3, UTC_TIMESTAMP());
CREATE TABLE IF NOT EXISTS official_travel (id CHAR(36) PRIMARY KEY, leader_person_id CHAR(36) NOT NULL, subject VARCHAR(300) NOT NULL, organiser VARCHAR(300) NOT NULL, place VARCHAR(300) NOT NULL, province VARCHAR(100) NOT NULL, travel_type VARCHAR(32) NOT NULL, vehicle VARCHAR(32) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, start_half VARCHAR(16) NOT NULL, end_half VARCHAR(16) NOT NULL, days DECIMAL(5,1) NOT NULL, funding_source VARCHAR(32) NOT NULL, cost_allowance DECIMAL(12,2) NOT NULL DEFAULT 0, cost_lodging DECIMAL(12,2) NOT NULL DEFAULT 0, cost_transport DECIMAL(12,2) NOT NULL DEFAULT 0, cost_registration DECIMAL(12,2) NOT NULL DEFAULT 0, attachment_id CHAR(36) NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, KEY official_travel_leader_index (leader_person_id), KEY official_travel_start_index (start_date), CONSTRAINT official_travel_leader_fk FOREIGN KEY (leader_person_id) REFERENCES person(id), CONSTRAINT official_travel_type_fk FOREIGN KEY (travel_type) REFERENCES official_travel_type(code), CONSTRAINT official_travel_attachment_fk FOREIGN KEY (attachment_id) REFERENCES attachment(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS official_travel_member (request_id CHAR(36) PRIMARY KEY, travel_id CHAR(36) NOT NULL, person_id CHAR(36) NOT NULL, created_at DATETIME NOT NULL, UNIQUE KEY official_travel_member_unique (travel_id, person_id), KEY official_travel_member_person_index (person_id), CONSTRAINT official_travel_member_request_fk FOREIGN KEY (request_id) REFERENCES request(id), CONSTRAINT official_travel_member_travel_fk FOREIGN KEY (travel_id) REFERENCES official_travel(id), CONSTRAINT official_travel_member_person_fk FOREIGN KEY (person_id) REFERENCES person(id)) DEFAULT CHARSET=utf8mb4;
